/*
# Seed sample lessons into the database

1. Data
- Inserts the 13 sample lessons for the literature and philosophy stream (Arabic, philosophy, history, foreign language, Islamic education) into `lessons`.

2. Safety
- Each lesson is inserted only if no lesson with the same title exists, so re-running this migration never creates duplicates.
- No existing rows are changed or removed.
*/

INSERT INTO lessons (title, subject_id, track, kind, keywords, sections)
SELECT v.title, v.subject_id, 'آداب وفلسفة', v.kind, v.keywords, v.sections
FROM (VALUES
  ('الشعر الجاهلي: البناء الفني للقصيدة', 'arabic', 'درس', ARRAY['الشعر الجاهلي', 'القصيدة', 'الوقوف على الأطلال', 'النسيب', 'الرحلة', 'الأغراض الشعرية', 'الجاهلية'],
   $j$[{"heading":"بنية القصيدة الجاهلية","body":"تتكون القصيدة غالباً من ثلاثة أجزاء: المقدمة الطللية أو النسيب، ثم الرحلة أو الوصف، ثم الغرض الرئيسي كالفخر أو المدح أو الرثاء."},{"heading":"الوقوف على الأطلال","body":"يمثل الوقوف على الديار المهجورة استحضاراً للذكرى وتأملاً في مرور الزمن، وهو مدخل فني يربط الشاعر بالماضي والمحبوبة."},{"heading":"خصائص اللغة والصورة","body":"تتميز الصورة الجاهلية بالحسية والوضوح، مع الاعتماد على التشبيه والاستعارة المستمدة من البيئة الصحراوية كالناقة والفرس والصحراء."}]$j$::jsonb),
  ('المعلقات: امرؤ القيس نموذجاً', 'arabic', 'ملخص', ARRAY['المعلقات', 'امرؤ القيس', 'معلقة امرؤ القيس', 'قفا نبك', 'الملك الضليل'],
   $j$[{"heading":"التعريف بالمعلقات","body":"المعلقات قصائد جاهلية طويلة اشتهرت بجودة نظمها ومكانتها بين العرب، ويرجح أنها كانت تعلق على جدار الكعبة، وهو ما لم يثبت تاريخياً بشكل قاطع."},{"heading":"معلقة امرؤ القيس","body":"مطلعها \"قفا نبكِ من ذكرى حبيبٍ ومنزلِ\"، وتعد من أشهر المعلقات، وفيها يبكي الشاعر الديار ويصف الليل والفرس والمغامرة، مما يجعلها نموذجاً للقصيدة الجاهلية الكاملة."}]$j$::jsonb),
  ('الشعر العباسي: أبو تمام والبحتري', 'arabic', 'درس', ARRAY['أبو تمام', 'البحتري', 'الشعر العباسي', 'البديع', 'الصنعة', 'الطبع', 'العصر العباسي'],
   $j$[{"heading":"مدرسة الصنعة","body":"يمثلها أبو تمام، وتقوم على الإغراق في المحسنات البديعية والمعاني الدقيقة، وقد جمع شعره في كتاب الحماسة."},{"heading":"مدرسة الطبع","body":"يمثلها البحتري، وتتميز بالسهولة والعذوبة والصورة الواضحة، مع الاعتماد على الطبع أكثر من التكلف."},{"heading":"المقارنة","body":"يقارن النقاد بين الاتجاهين، فيرى بعضهم أن أبا تمام يمثل الابتكار الفني، ويرى آخرون أن البحتري يمثل جمال الموسيقى والسلاسة."}]$j$::jsonb),
  ('المدرسة الرومانسية: جبران خليل جبران', 'arabic', 'درس', ARRAY['جبران', 'جبران خليل جبران', 'الرومانسية', 'المهجر', 'النثر الشعري', 'الرابطة القلمية'],
   $j$[{"heading":"أدب المهجر","body":"ظهر أدب المهجر في أمريكا الشمالية والجنوبية على يد أدباء عرب مثل جبران ونعيمة والريحاني، وأسسوا الرابطة القلمية."},{"heading":"ملامح الرومانسية","body":"تتميز بالتمرد على القيود التقليدية، والتعبير عن الذات والعاطفة، والحنين إلى الطبيعة، والدعوة إلى الحرية والتجديد."},{"heading":"من آثار جبران","body":"من أشهر أعماله \"النبي\" و\"الأجنحة المتكسرة\"، وتقوم كتاباته على أسلوب شعري حكيم يمزج بين الفلسفة والوجدان."}]$j$::jsonb),
  ('الرواية العربية: نجيب محفوظ', 'arabic', 'ملخص', ARRAY['نجيب محفوظ', 'الرواية', 'الرواية العربية', 'الثلاثية', 'بين القصرين', 'الواقعية'],
   $j$[{"heading":"مكانة محفوظ","body":"نجيب محفوظ أول عربي يفوز بجائزة نوبل في الأدب سنة 1988، وقد كتب الرواية الواقعية التي تصور المجتمع المصري بعمق."},{"heading":"الثلاثية","body":"تتكون من \"بين القصرين\" و\"قصر الشوق\" و\"السكرية\"، وتتبع ثلاثة أجيال من أسرة واحدة في القاهرة خلال فترة ما بين الحربين العالميتين."}]$j$::jsonb),
  ('تمرين محلول: تحليل نص شعري', 'arabic', 'تمرين', ARRAY['تحليل نص', 'تمرين', 'نص شعري', 'المنهجية', 'تحليل'],
   $j$[{"heading":"منهجية التحليل","body":"اقرأ النص قراءة أولى لفهم الفكرة العامة، ثم حدد الغرض الشعري، ثم اعرض الصور البيانية والمحسنات، وأخيراً اربط الأسلوب بالمعنى والغرض."},{"heading":"مثال تطبيقي","body":"في بيت شعري فيه تشبيه، اذكر المشبه والمشبه به ووجه الشبه، ثم بين أثر هذا التشبيه في إيضاح المعنى أو تقويته."}]$j$::jsonb),
  ('مفهوم الحرية', 'philosophy', 'درس', ARRAY['الحرية', 'الإرادة', 'الحتمية', 'الجبر', 'الاختيار', 'المسؤولية'],
   $j$[{"heading":"تعريف الحرية","body":"قدرة الإنسان على الاختيار والفعل وفق إرادته العاقلة دون إكراه."},{"heading":"الحرية السلبية والإيجابية","body":"السلبية: غياب القيود والإكراه الخارجي. الإيجابية: القدرة على تحقيق الذات والتحرر من الجهل والأهواء."},{"heading":"الإشكالية","body":"هل الإنسان حر فعلاً، أم أن أفعاله محكومة بالحتمية؟"}]$j$::jsonb),
  ('الوجودية عند سارتر', 'philosophy', 'درس', ARRAY['سارتر', 'الوجودية', 'الوجود يسبق الماهية', 'الحرية والمسؤولية', 'القلق'],
   $j$[{"heading":"الوجود يسبق الماهية","body":"يرى سارتر أن الإنسان يوجد أولاً ثم يصنع ماهيته بأفعاله واختياراته، فليس له طبيعة ثابتة سابقة على وجوده."},{"heading":"الحرية والمسؤولية","body":"الإنسان محكوم بالحرية، أي أنه مسؤول عن كل اختيار يقوم به، ولا يمكنه التهرب من المسؤولية بإلقائها على القدر أو المجتمع."}]$j$::jsonb),
  ('الدولة الفاضلة عند أفلاطون', 'philosophy', 'ملخص', ARRAY['أفلاطون', 'الجمهورية', 'الدولة الفاضلة', 'العدالة', 'الفلاسفة الملوك', 'الطبقات'],
   $j$[{"heading":"تعريف العدالة","body":"تقوم الدولة الفاضلة عند أفلاطون على العدالة، وهي أن يقوم كل فرد بالوظيفة التي تناسب طبعه دون تدخل في وظائف الآخرين."},{"heading":"الطبقات الثلاث","body":"تنقسم المدينة إلى طبقة الحكام الفلاسفة، وطبقة الجند، وطبقة المنتجين، ويقابلها في النفس العقل والغضب والشهوة."}]$j$::jsonb),
  ('الحرب العالمية الأولى: الأسباب', 'history', 'درس', ARRAY['الحرب العالمية الأولى', 'الحلفاء', 'المحور', 'التحالفات', 'الإمبريالية', 'سراييفو'],
   $j$[{"heading":"الأسباب العامة","body":"تمثلت في التنافس الاستعماري، وسباق التسلح، وتشكل التحالفات الكبرى، والنزعة القومية المتطرفة."},{"heading":"الشرارة","body":"اغتيال ولي عهد النمسا فرانز فرديناند في سراييفو سنة 1914 كان الحدث المباشر الذي فجر الحرب."}]$j$::jsonb),
  ('ثورة نوفمبر 1954 في الجزائر', 'history', 'ملخص', ARRAY['ثورة نوفمبر', 'ثورة التحرير', '1954', 'جبهة التحرير الوطني', 'الجزائر', 'الاستعمار الفرنسي'],
   $j$[{"heading":"اندلاع الثورة","body":"اندلعت الثورة في فاتح نوفمبر 1954 بقيادة جبهة التحرير الوطني، واستهدفت عدة مواقع عسكرية وإدارية في مختلف أنحاء الوطن."},{"heading":"أهدافها","body":"تمثلت في استرجاع السيادة الوطنية وإقامة دولة جزائرية مستقلة ديمقراطية واجتماعية في إطار المبادئ الإسلامية."}]$j$::jsonb),
  ('تقنيات الفهم القرائي في اللغة الإنجليزية', 'foreign', 'ملخص', ARRAY['english', 'reading', 'الفهم القرائي', 'الإنجليزية', 'اللغة الإنجليزية', 'قراءة', 'skimming', 'scanning'],
   $j$[{"heading":"Skimming و Scanning","body":"Skimming هو قراءة سريعة لفهم الفكرة العامة، أما Scanning فهو البحث السريع عن معلومة محددة مثل تاريخ أو اسم."},{"heading":"استنتاج المعنى","body":"عند مواجهة كلمة مجهولة، اعتمد على السياق والجذور اللغوية والأمثلة المحيطة قبل اللجوء إلى القاموس."}]$j$::jsonb),
  ('مقاصد الشريعة: الضروريات الخمس', 'islamic', 'درس', ARRAY['مقاصد الشريعة', 'الضروريات الخمس', 'حفظ الدين', 'حفظ النفس', 'حفظ العقل', 'حفظ المال', 'حفظ النسل'],
   $j$[{"heading":"تعريف المقاصد","body":"مقاصد الشريعة هي الغايات والحكم التي أرادها الشارع من تشريع الأحكام لتحقيق مصالح العباد في الدنيا والآخرة."},{"heading":"الضروريات الخمس","body":"حفظ الدين، وحفظ النفس، وحفظ العقل، وحفظ النسل، وحفظ المال، وهي الأمور التي لا تستقيم حياة الناس دونها."}]$j$::jsonb)
) AS v(title, subject_id, kind, keywords, sections)
WHERE NOT EXISTS (SELECT 1 FROM lessons l WHERE l.title = v.title);
